import { createContext, useContext, useState, ReactNode } from 'react';

import { PostNavigationData } from '../types';

interface PostNavigationContextType {
  navigationData: PostNavigationData | null;
  setNavigationData: (data: PostNavigationData | null) => void;
  preloadedImages: Map<string, boolean>;
  preloadImage: (imageUrl: string) => void;
}

const PostNavigationContext = createContext<PostNavigationContextType | undefined>(undefined);

export const usePostNavigation = () => {
  const context = useContext(PostNavigationContext);
  if (context === undefined) {
    throw new Error('usePostNavigation must be used within a PostNavigationProvider');
  }
  return context;
};

interface PostNavigationProviderProps {
  children: ReactNode;
}

export const PostNavigationProvider = ({ children }: PostNavigationProviderProps) => {
  const [navigationData, setNavigationData] = useState<PostNavigationData | null>(null);
  const [preloadedImages, setPreloadedImages] = useState<Map<string, boolean>>(new Map());

  const preloadImage = (imageUrl: string) => {
    if (preloadedImages.has(imageUrl)) return;

    const img = new Image();
    img.onload = () => {
      setPreloadedImages(prev => new Map(prev).set(imageUrl, true));
    };
    img.onerror = () => {
      setPreloadedImages(prev => new Map(prev).set(imageUrl, false));
    };
    img.src = imageUrl;
  };

  return (
    <PostNavigationContext.Provider
      value={{
        navigationData,
        setNavigationData,
        preloadedImages,
        preloadImage,
      }}
    >
      {children}
    </PostNavigationContext.Provider>
  );
};
