import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';

// Types
export interface NavigationPost {
  id: string;
  title: string;
  image_url: string;
  user_id: string;
}

export interface NavigationData {
  posts: NavigationPost[];
  currentIndex: number;
  source: 'home' | 'collection' | 'tag' | 'search' | 'user' | 'photogrid';
  sourceId?: string;
}

export interface NavigationHistory {
  path: string;
  data: NavigationData;
  timestamp: number;
}

export interface WizardInitialImage {
  id: string;
  src: string;
  title: string;
  realDatabaseId?: string;
  selected: boolean;
}

interface NavigationStore {
  // Current navigation state
  navigationData: NavigationData | null;

  // Navigation history stack
  history: NavigationHistory[];

  // Wizard state (replaces sessionStorage)
  wizardInitialImage: WizardInitialImage | null;
  wizardReturnPath: string | null;

  // Global Creation Wizard state
  creationWizardOpen: boolean;
  creationWizardMode: 'default' | 'page'; // Add more modes if needed

  // Actions
  setNavigationData: (data: NavigationData | null) => void;
  updateCurrentIndex: (index: number) => void;

  // History management
  pushHistory: (path: string, data: NavigationData) => void;
  popHistory: () => NavigationHistory | null;
  clearHistory: () => void;
  canGoBack: () => boolean;

  // Wizard actions
  setWizardImage: (image: WizardInitialImage | null, returnPath?: string) => void;
  clearWizardImage: () => void;
  setCreationWizardOpen: (open: boolean, mode?: 'default' | 'page') => void;

  // Preloading
  preloadImage: (url: string) => void;

  // Reset all
  reset: () => void;
}

// Preload image helper
const preloadImageHelper = (url: string) => {
  if (!url) return;
  const img = new Image();
  img.src = url;
};

export const useNavigationStore = create<NavigationStore>()(
  persist(
    (set, get) => ({
      // Initial state
      navigationData: null,
      history: [],
      wizardInitialImage: null,
      wizardReturnPath: null,
      creationWizardOpen: false,
      creationWizardMode: 'default',

      // Set navigation data
      setNavigationData: (data) => {
        set({ navigationData: data });
      },

      // Update just the current index (faster than full data update)
      updateCurrentIndex: (index) => {
        const current = get().navigationData;
        if (current) {
          set({
            navigationData: { ...current, currentIndex: index }
          });
        }
      },

      // Push navigation to history stack
      pushHistory: (path, data) => {
        const state = get();
        const newHistory = [...state.history, {
          path,
          data,
          timestamp: Date.now()
        }];

        // Limit history to 50 entries
        const limitedHistory = newHistory.slice(-50);

        set({
          history: limitedHistory,
          navigationData: data
        });
      },

      // Pop from history stack
      popHistory: () => {
        const state = get();
        if (state.history.length === 0) return null;

        const newHistory = [...state.history];
        const previous = newHistory.pop()!;

        const previousData = newHistory.length > 0
          ? newHistory[newHistory.length - 1].data
          : null;

        set({
          history: newHistory,
          navigationData: previousData
        });

        return previous;
      },

      // Clear history
      clearHistory: () => {
        set({ history: [] });
      },

      // Check if can go back
      canGoBack: () => {
        return get().history.length > 1;
      },

      // Set wizard image (replaces sessionStorage)
      setWizardImage: (image, returnPath) => {
        set({
          wizardInitialImage: image,
          wizardReturnPath: returnPath || null
        });
      },

      // Clear wizard image
      clearWizardImage: () => {
        set({
          wizardInitialImage: null,
          wizardReturnPath: null
        });
      },

      // Set global creation wizard open state
      setCreationWizardOpen: (open, mode = 'default') => {
        set({
          creationWizardOpen: open,
          creationWizardMode: mode
        });
      },

      // Preload image
      preloadImage: (url) => {
        preloadImageHelper(url);
      },

      // Reset entire store
      reset: () => {
        set({
          navigationData: null,
          history: [],
          wizardInitialImage: null,
          wizardReturnPath: null,
          creationWizardOpen: false,
          creationWizardMode: 'default'
        });
      }
    }),
    {
      name: 'pm-pics-navigation', // localStorage key
      storage: createJSONStorage(() => localStorage), // Use localStorage

      // Only persist certain fields (not history - too large)
      partialize: (state) => ({
        navigationData: state.navigationData,
        wizardInitialImage: state.wizardInitialImage,
        wizardReturnPath: state.wizardReturnPath,
        // Don't persist history - it's too large and not needed across sessions
      }),

      // Version for migrations
      version: 1,

      // Skip hydration on server (if using SSR)
      skipHydration: false,
    }
  )
);

// Selectors for better performance (only re-render when needed)
export const selectNavigationData = (state: NavigationStore) => state.navigationData;
export const selectCurrentIndex = (state: NavigationStore) => state.navigationData?.currentIndex;
export const selectPosts = (state: NavigationStore) => state.navigationData?.posts;
export const selectCanGoBack = (state: NavigationStore) => state.canGoBack();
export const selectWizardImage = (state: NavigationStore) => state.wizardInitialImage;
export const selectWizardReturnPath = (state: NavigationStore) => state.wizardReturnPath;
export const selectCreationWizardOpen = (state: NavigationStore) => state.creationWizardOpen;
export const selectCreationWizardMode = (state: NavigationStore) => state.creationWizardMode;

